from typing import List
from math import gcd
from functools import lru_cache

class Solution:
    def maxScore(self, nums: List[int]) -> int:
        m = len(nums)
        g = [[0] * m for _ in range(m)]

        for i in range(m):
            for j in range(i + 1, m):
                g[i][j] = gcd(nums[i], nums[j])

        full_mask = (1 << m) - 1

        @lru_cache(None)
        def dp(mask: int) -> int:
            if mask == full_mask:
                return 0

            op = mask.bit_count() // 2 + 1

            first = 0
            while mask & (1 << first):
                first += 1

            best = 0
            for j in range(first + 1, m):
                if not (mask & (1 << j)):
                    new_mask = mask | (1 << first) | (1 << j)
                    best = max(best, op * g[first][j] + dp(new_mask))

            return best

        return dp(0)
```

