class Solution:
    def abbreviateProduct(self, left: int, right: int) -> str:
        import sys

        if hasattr(sys, "set_int_max_str_digits"):
            try:
                sys.set_int_max_str_digits(0)
            except Exception:
                pass

        product = 1
        for x in range(left, right + 1):
            product *= x

        zeros = 0
        while product % 10 == 0:
            product //= 10
            zeros += 1

        try:
            s = str(product)
        except ValueError:
            base = 10 ** 9
            parts = []
            n = product
            while n:
                n, rem = divmod(n, base)
                parts.append(rem)
            if not parts:
                s = "0"
            else:
                s = str(parts[-1]) + ''.join(f"{p:09d}" for p in reversed(parts[:-1]))

        if len(s) > 10:
            return f"{s[:5]}...{s[-5:]}e{zeros}"
        return f"{s}e{zeros}"
