from collections import deque

class Solution:
    def eventualSafeNodes(self, graph: List[List[int]]) -> List[int]:
        n = len(graph)
        reverse_graph = [[] for _ in range(n)]
        outdegree = [0] * n

        for node in range(n):
            outdegree[node] = len(graph[node])
            for neighbor in graph[node]:
                reverse_graph[neighbor].append(node)

        queue = deque()
        for node in range(n):
            if outdegree[node] == 0:
                queue.append(node)

        safe = [False] * n

        while queue:
            node = queue.popleft()
            safe[node] = True

            for prev in reverse_graph[node]:
                outdegree[prev] -= 1
                if outdegree[prev] == 0:
                    queue.append(prev)

        return [node for node in range(n) if safe[node]]
```

