class Solution:
    def canCross(self, stones: List[int]) -> bool:
        n = len(stones)

        if stones[1] != 1:
            return False

        for i in range(1, n):
            if stones[i] - stones[i - 1] > i:
                return False

        last = stones[-1]
        pos_to_idx = {pos: i for i, pos in enumerate(stones)}
        dp = [set() for _ in range(n)]
        dp[0].add(0)

        for i, pos in enumerate(stones):
            for k in dp[i]:
                for jump in (k - 1, k, k + 1):
                    if jump <= 0:
                        continue

                    nxt = pos + jump
                    if nxt == last:
                        return True

                    if nxt in pos_to_idx:
                        dp[pos_to_idx[nxt]].add(jump)

        return False
