class Solution:
    def licenseKeyFormatting(self, s: str, k: int) -> str:
        chars = [c.upper() for c in s if c != '-']
        n = len(chars)

        if n == 0:
            return ""

        first = n % k
        groups = []

        if first:
            groups.append(''.join(chars[:first]))

        for i in range(first, n, k):
            groups.append(''.join(chars[i:i + k]))

        return '-'.join(groups)
