from functools import lru_cache

class Solution:
    def maximumANDSum(self, nums: List[int], numSlots: int) -> int:
        powers = [1] * numSlots
        for i in range(1, numSlots):
            powers[i] = powers[i - 1] * 3

        n = len(nums)

        @lru_cache(None)
        def dp(i: int, mask: int) -> int:
            if i == n:
                return 0

            best = 0
            for slot in range(numSlots):
                count = (mask // powers[slot]) % 3
                if count < 2:
                    best = max(
                        best,
                        (nums[i] & (slot + 1)) + dp(i + 1, mask + powers[slot])
                    )

            return best

        return dp(0, 0)
