class Solution:
    def maxTotalFruits(self, fruits: List[List[int]], startPos: int, k: int) -> int:
        def steps_needed(left_pos: int, right_pos: int) -> int:
            if right_pos <= startPos:
                return startPos - left_pos
            if left_pos >= startPos:
                return right_pos - startPos
            return min(
                2 * (startPos - left_pos) + (right_pos - startPos),
                (startPos - left_pos) + 2 * (right_pos - startPos)
            )

        ans = 0
        cur = 0
        left = 0

        for right in range(len(fruits)):
            cur += fruits[right][1]

            while left <= right and steps_needed(fruits[left][0], fruits[right][0]) > k:
                cur -= fruits[left][1]
                left += 1

            ans = max(ans, cur)

        return ans
