class Solution:
    def minMalwareSpread(self, graph: List[List[int]], initial: List[int]) -> int:
        n = len(graph)
        initial_set = set(initial)
        saved = {node: 0 for node in initial}
        visited = [False] * n

        for i in range(n):
            if i in initial_set or visited[i]:
                continue

            stack = [i]
            visited[i] = True
            component_size = 0
            infected_neighbors = set()

            while stack:
                node = stack.pop()
                component_size += 1

                for nei in range(n):
                    if graph[node][nei] == 0:
                        continue

                    if nei in initial_set:
                        infected_neighbors.add(nei)
                    elif not visited[nei]:
                        visited[nei] = True
                        stack.append(nei)

            if len(infected_neighbors) == 1:
                source = next(iter(infected_neighbors))
                saved[source] += component_size

        answer = min(initial)
        best_saved = -1

        for node in sorted(initial):
            if saved[node] > best_saved:
                best_saved = saved[node]
                answer = node

        return answer
