        total = sum(nums)
        if total % k != 0:
            return False

        target = total // k
        nums.sort()

        if nums[-1] > target:
            return False

        n = len(nums)
        full_mask = (1 << n) - 1

        dp = [-1] * (1 << n)
        dp[0] = 0

        for mask in range(1 << n):
            if dp[mask] == -1:
                continue

            remaining = target - dp[mask]

            for i in range(n):
                if mask & (1 << i):
                    continue

                if nums[i] > remaining:
                    break

                next_mask = mask | (1 << i)
                if dp[next_mask] == -1:
                    dp[next_mask] = (dp[mask] + nums[i]) % target

