from typing import List
from functools import lru_cache

class Solution:
    def minStickers(self, stickers: List[str], target: str) -> int:
        letters = sorted(set(target))
        k = len(letters)
        idx = {ch: i for i, ch in enumerate(letters)}

        target_count = [0] * k
        for ch in target:
            target_count[idx[ch]] += 1

        vecs = []
        for sticker in stickers:
            v = [0] * k
            for ch in sticker:
                if ch in idx:
                    i = idx[ch]
                    if v[i] < target_count[i]:
                        v[i] += 1
            if any(v):
                vecs.append(tuple(v))

        if not vecs:
            return -1

        vecs = list(set(vecs))

        filtered = []
        for i, v in enumerate(vecs):
            dominated = False
            for j, u in enumerate(vecs):
                if i != j and all(v[x] <= u[x] for x in range(k)):
                    dominated = True
                    break
            if not dominated:
                filtered.append(v)

        vecs = sorted(filtered, key=sum, reverse=True)

        candidates = [[] for _ in range(k)]
        for si, v in enumerate(vecs):
            for i, cnt in enumerate(v):
                if cnt:
                    candidates[i].append(si)

        for i in range(k):
            if target_count[i] and not candidates[i]:
                return -1

        INF = 10 ** 9

        @lru_cache(None)
        def dfs(rem):
            if not any(rem):
                return 0

            chosen = -1
            best_count = INF
            for i, need in enumerate(rem):
                if need > 0 and len(candidates[i]) < best_count:
                    best_count = len(candidates[i])
                    chosen = i

            ans = INF
            for si in candidates[chosen]:
                sticker = vecs[si]
                nxt = tuple(max(0, rem[i] - sticker[i]) for i in range(k))
                sub = dfs(nxt)
                if sub + 1 < ans:
                    ans = sub + 1

            return ans

        res = dfs(tuple(target_count))
        return -1 if res >= INF else res
