from typing import List
from functools import lru_cache

class Solution:
    def earliestAndLatest(self, n: int, firstPlayer: int, secondPlayer: int) -> List[int]:
        @lru_cache(None)
        def dp(m: int, a: int, b: int):
            if a > m + 1 - b:
                return dp(m, m + 1 - b, m + 1 - a)

            if a + b == m + 1:
                return (1, 1)

            winner_options = []

            for i in range(1, m // 2 + 1):
                j = m + 1 - i

                if i == a or j == a:
                    winner_options.append((a,))
                elif i == b or j == b:
                    winner_options.append((b,))
                else:
                    winner_options.append((i, j))

            if m % 2 == 1:
                winner_options.append((m // 2 + 1,))

            counts = {(0, 0)}

            for options in winner_options:
                nxt_counts = set()
                for ca, cb in counts:
                    for w in options:
                        nxt_counts.add((ca + (w < a), cb + (w < b)))
                counts = nxt_counts

            next_m = (m + 1) // 2
            earliest = 10**9
            latest = 0

            for ca, cb in counts:
                na = ca + 1
                nb = cb + 1
                e, l = dp(next_m, na, nb)
                earliest = min(earliest, e + 1)
                latest = max(latest, l + 1)

            return (earliest, latest)

        return list(dp(n, firstPlayer, secondPlayer))
