        coprime = [[] for _ in range(51)]
        for x in range(1, 51):
            for y in range(1, 51):
                if gcd(x, y) == 1:
                    coprime[x].append(y)

        ans = [-1] * n
        latest_depth = [-1] * 51
        latest_node = [-1] * 51

        stack = [(0, -1, 0, 0, -1, -1)]

        while stack:
            node, parent, depth, state, prev_depth, prev_node = stack.pop()
            val = nums[node]

            if state == 0:
                best_depth = -1
                best_node = -1

                for other_val in coprime[val]:
                    if latest_depth[other_val] > best_depth:
                        best_depth = latest_depth[other_val]
                        best_node = latest_node[other_val]

                ans[node] = best_node

                old_depth = latest_depth[val]
                old_node = latest_node[val]

                latest_depth[val] = depth
                latest_node[val] = node

                stack.append((node, parent, depth, 1, old_depth, old_node))

                for nei in graph[node]:
                    if nei != parent:
                        stack.append((nei, node, depth + 1, 0, -1, -1))

            else:
                latest_depth[val] = prev_depth
                latest_node[val] = prev_node

        return ans
